# Edit the notebook, not this file, then rebuild.
# The action at the end of this cell is in r19_shift_test.py.
# CELL 13b: TEST THE PROPOSED SHIFTS   (Eir 2.0.13)
# ============================================================================
# The half-lattice screen proposes a candidate position for a cation whose
# coordination sphere is split. Up to here that proposal is a column: a spread
# that would improve and a bond valence sum that would move. This cell tests
# it properly, by applying the shift to a COPY of each CIF, running the whole
# analysis again, and writing a parallel dataset.
#
# What that buys, that the per-site numbers do not:
#
#   - every downstream quantity is recomputed, not just the shifted site. The
#     GII, the anion sums, the diagnosis and all five screens are evaluated on
#     the shifted structure, so a shift that fixes one cation and breaks the
#     rest is visible.
#   - the comparison is like for like, because the shifted CIF goes through
#     exactly the same code path as the original.
#   - it can DISAGREE. A proposal that leaves the structure no better is
#     reported as such, which is what makes the others worth believing.
#
# WHAT THIS IS NOT
# It is not a correction. The originals are never modified; the shifted files
# go to a separate directory, each carrying a header recording what was moved
# and why, and the output is a separate CSV to be read ALONGSIDE the quality
# CSV, never in place of it. A shift that improves the geometry is evidence of
# a mixed-origin deposition, not proof of one, and cannot be proven from a
# single deposited CIF. What this cell provides is the strongest evidence
# obtainable without going back to the diffraction data.

import os
import re
import shutil
from datetime import datetime

import pandas as pd


def _shift_cif_text(cif_text, site_label, shift, note=None):
    """
    Return the CIF with one site's fractional coordinates translated.

    Edits the atom_site loop in place rather than round-tripping through a
    parser, so everything else in the file survives untouched, including the
    fields Eir reads for provenance. Standard uncertainties are preserved: a
    translation does not change them, so 0.0250(8) shifted by 1/2 becomes
    0.5250(8).

    Returns (new_text, applied) where applied is False if the site or the
    coordinate columns could not be located, so a silent no-op is impossible.
    """
    lines = cif_text.split('\n')

    # locate the atom_site loop and the column order within it
    tags, start = [], None
    for i, ln in enumerate(lines):
        t = ln.strip()
        if t.startswith('_atom_site_'):
            if start is None or not tags:
                start = i
            tags.append(t.split()[0])
        elif tags and t and not t.startswith('_'):
            break
    if not tags:
        return cif_text, False
    try:
        ix = tags.index('_atom_site_label')
        cx = tags.index('_atom_site_fract_x')
        cy = tags.index('_atom_site_fract_y')
        cz = tags.index('_atom_site_fract_z')
    except ValueError:
        return cif_text, False

    data_start = start + len(tags)

    def _shift_value(txt, delta):
        """Add delta to a CIF number, keeping any standard uncertainty."""
        # CIFs write '1.' and '0.' as well as '0.2500'; a pattern requiring a
        # digit after the point rejects them. ICSD 420711 has Ga at fract_x
        # '1.' and was silently skipped for exactly that reason.
        m = re.match(r'^\s*([+-]?(?:\d+\.?\d*|\.\d+))(\(\d+\))?\s*$', txt)
        if not m:
            return None
        v = (float(m.group(1)) + delta) % 1.0
        digits = len(m.group(1).split('.')[1]) if '.' in m.group(1) else 4
        return f'{v:.{max(digits, 4)}f}' + (m.group(2) or '')

    applied = False
    for i in range(data_start, len(lines)):
        row = lines[i].strip()
        if not row or row.startswith('_') or row.startswith('loop_') \
                or row.startswith('#') or row.startswith('data_'):
            if applied:
                break
            continue
        parts = lines[i].split()
        if len(parts) < len(tags) or parts[ix] != site_label:
            continue
        new = list(parts)
        ok = True
        for col, d in ((cx, shift[0]), (cy, shift[1]), (cz, shift[2])):
            s = _shift_value(parts[col], d)
            if s is None:
                ok = False
                break
            new[col] = s
        if not ok:
            continue
        lines[i] = ' '.join(new)
        applied = True
        break

    if not applied:
        return cif_text, False

    header = [
        '# ---------------------------------------------------------------',
        '# MODIFIED COPY - NOT THE DEPOSITED STRUCTURE',
        f'# Site {site_label} translated by ({shift[0]}, {shift[1]}, {shift[2]})',
        '# by Eir 2.0.2, to TEST a suspected mixed-origin deposition.',
        '# This is a hypothesis under test, not a correction. The deposited',
        '# entry is unchanged; see the original CIF for the data of record.',
        '#',
        '# Only the fractional coordinates were touched. Any Wyckoff symbol,',
        '# site multiplicity or symmetry-equivalent count in this file still',
        '# describes the ORIGINAL position and is now inconsistent with the',
        '# coordinates. That is deliberate: rewriting them would assert the',
        '# shift is right, which is the question rather than the answer.',
    ]
    if note:
        header.append(f'# {note}')
    header += [f'# generated {datetime.now().isoformat(timespec="seconds")}',
               '# ---------------------------------------------------------']
    return '\n'.join(header + lines), True


def test_proposed_shifts(dfq, cif_directory, output_dir=None, verbose=True):
    """
    Apply every proposed shift to a copy, re-analyse, and write the results.

    v2.0.3: the verdict is decided by the SCREENS first and the GII second.

    The previous ladder was ordered on the GII, with the screens acting only as
    a veto and as a gate on the top two tiers. A shift could therefore clear
    every screen it had been failing and still be reported as not supported.
    ICSD 209078 (CaTiO3) settles it: Ti is deposited with a first-shell spread
    of 1.79 A and bond lengths of 1.65, 2.20 and 2.97 A, the shift takes the
    spread to 1.02 A and clears the one screen that was failing, and the GII
    rises from 0.207 to 0.422. The old rule returned NOT supported.

    The GII rises because the deposited Ti sits at CN 4 and sums to 3.890 v.u.,
    2.75% from formal: a short four-coordinate sum lands where a normal six-
    coordinate sum would. Bond valence is degenerate between too few bonds too
    short and the right number at the right length, so it cannot arbitrate a
    question about geometry. The screens can, and the verdict now keys on them.

    Where the two disagree the disagreement is REPORTED rather than resolved,
    in gii_direction and screens_gii_disagree. Those structures are the
    informative ones and should not be collapsed into a single word.

    Args:
        dfq: the post-processed quality DataFrame
        cif_directory: where the original CIFs live
        output_dir: where to write; defaults to <cif_directory>/outputs

    Returns the comparison DataFrame, one row per tested structure and variant.
    """
    if dfq is None or 'proposed_shift' not in dfq.columns:
        print('No proposed_shift column. Run the batch under Eir 2.0.2 first.')
        return None

    prop = dfq[dfq['proposed_shift'].notna()].copy()
    if not len(prop):
        print('No shifts proposed; nothing to test.')
        return None

    output_dir = output_dir or os.path.join(cif_directory, 'outputs')
    shifted_dir = os.path.join(output_dir, 'shifted_cifs')
    os.makedirs(shifted_dir, exist_ok=True)

    _SCREENS_BEFORE = ('anion_packing_plausible',
                       'structure_core_geometry_plausible',
                       'structure_bvs_geometry_plausible',
                       'structure_cn_plausible')
    _SCREENS_AFTER = ('anion_packing_after', 'core_geometry_after',
                      'bvs_geometry_after', 'cn_plausible_after')

    def _num(v):
        """A float, or None. Distinguishes a genuine zero from a missing value."""
        x = pd.to_numeric(pd.Series([v]), errors='coerce').iloc[0]
        return None if x != x else float(x)

    def _verdict(before, after, gb, ga):
        """
        Screens first, GII second.

        The screens test the physical claim the proposal makes: that the ions
        sit where the anion sublattice expects them. The GII is a derived index
        that cannot distinguish a deficient coordination sphere from a sound
        one, so it ranks within a screen outcome rather than across outcomes.
        """
        if ga is None:
            return 'inconclusive'
        if after > before:
            # More screens failing than before is disqualifying however much
            # the GII improved: the shift has moved the problem, not fixed it.
            return 'NOT supported'
        if before == 0 and after == 0:
            # Nothing was failing, so the re-run cannot adjudicate the proposal
            # either way. Reporting this as an outcome is honest; calling it
            # marginal on a GII change is not.
            return 'not diagnostic'
        if after == 0:
            return 'strongly supported' if before >= 2 else 'supported'
        if after < before:
            return 'partially supported'
        # after == before > 0: the shift changed nothing the screens can see
        return 'marginal' if (gb is not None and ga < gb) else 'NOT supported'

    print('=' * 78)
    print(f'TESTING {len(prop)} PROPOSED SHIFTS IN {prop["filename"].nunique()} STRUCTURES')
    print('=' * 78)
    print('  Originals are not modified. Shifted copies go to:')
    print(f'    {shifted_dir}')
    print()

    rows, written, skipped = [], [], []
    for fn, grp in prop.groupby('filename'):
        src = os.path.join(cif_directory, fn)
        if not os.path.exists(src):
            skipped.append((fn, 'CIF not found'))
            rows.append({'filename': fn, 'verdict': 'not tested: CIF not found'})
            continue
        try:
            with open(src, 'r', encoding='utf-8', errors='replace') as fh:
                original = fh.read()
        except OSError as e:
            skipped.append((fn, f'unreadable: {e}'))
            rows.append({'filename': fn, 'verdict': f'not tested: {e}'})
            continue

        try:
            _vec_str = str(grp.iloc[0]['proposed_shift'])
            shift_vec = [float(x) for x in _vec_str.split(',')]
        except ValueError:
            skipped.append((fn, 'unparseable shift'))
            continue

        # Two hypotheses, not one.
        #
        #   single_site  moves only the cations the screen named. Right when a
        #                lone cation was deposited on the wrong Wyckoff site.
        #   all_cations  moves every cation by the same vector. Right when the
        #                cation and anion sublattices as a whole sit on
        #                different origins, which a single-site move cannot
        #                describe.
        #
        # Both are tested and both are reported. Picking one silently would
        # hide the case where neither works, which is itself informative.
        named = [r.get('site_label') for _, r in grp.iterrows()]
        all_cats = sorted(set(dfq.loc[dfq['filename'] == fn, 'site_label']
                              .dropna().astype(str)))
        variants = [('single_site', named), ('all_cations', all_cats)]
        if set(named) == set(all_cats):
            variants = [('single_site', named)]

        for variant, labels in variants:
            text, detail, applied_any = original, [], False
            for lbl in labels:
                text, ok = _shift_cif_text(
                    text, lbl, shift_vec,
                    note=str(grp.iloc[0].get('shift_evidence') or ''))
                if ok:
                    applied_any = True
                    # v2.0.3: the label alone. Concatenating the vector with a
                    # '+' produced strings like 'Mn1+(0.5,0.0,0.0)', which read
                    # as manganese(I) rather than as site Mn1 plus a vector, in
                    # a column that ships as supplementary data.
                    detail.append(lbl)
                else:
                    skipped.append((fn, f'could not locate site {lbl}'))
            if not applied_any:
                rows.append({'filename': fn, 'variant': variant,
                             'icsd_code': grp.iloc[0].get('icsd_code'),
                             'chemical_formula': grp.iloc[0].get('chemical_formula'),
                             'verdict': 'not tested: site not found in CIF'})
                continue

            stem, ext = os.path.splitext(fn)
            dst = os.path.join(shifted_dir, f'{stem}__{variant}{ext}')
            with open(dst, 'w', encoding='utf-8') as fh:
                fh.write(text)
            written.append(dst)

            before = grp.iloc[0]
            n_screens_before = sum(1 for k in _SCREENS_BEFORE
                                   if str(before.get(k)).lower() == 'false')

            res = process_single_cif(dst)
            if not res.get('success'):
                rows.append({'filename': fn, 'variant': variant,
                             'icsd_code': before.get('icsd_code'),
                             'chemical_formula': before.get('chemical_formula'),
                             'sites_shifted': ', '.join(detail),
                             'shift_vector': f"({_vec_str})",
                             'shift_applied': f"{', '.join(detail)} by ({_vec_str})",
                             'gii_before': _num(before.get('gii')),
                             'gii_after': None,
                             'n_screens_failed_before': n_screens_before,
                             'n_screens_failed_after': None,
                             'gii_ratio': None,
                             'gii_direction': None,
                             'screens_gii_disagree': False,
                             'verdict': f"re-analysis failed: {res.get('error')}"})
                continue

            # v2.0.3: an explicit None test throughout. `x or default` treats a
            # genuine GII or WAGII of exactly 0.0 as missing, which is the one
            # value a perfectly regular structure can legitimately return.
            g0 = _num(before.get('gii'))
            g1 = _num(res.get('gii'))
            wa = _num(res.get('wagii'))

            row = {
                'filename': fn,
                'variant': variant,
                'icsd_code': before.get('icsd_code'),
                'chemical_formula': before.get('chemical_formula'),
                'shift_applied': '; '.join(detail),
                'gii_before': round(g0, 4) if g0 is not None else None,
                'gii_after': round(g1, 4) if g1 is not None else None,
                'wagii_after': round(wa, 4) if wa is not None else None,
                'anion_packing_after': res.get('anion_packing_plausible'),
                'core_geometry_after': res.get('core_geometry_plausible'),
                'bvs_geometry_after': res.get('bvs_geometry_plausible'),
                'cn_plausible_after': res.get('cn_plausible'),
                'n_shift_proposed_after': res.get('n_sites_shift_proposed'),
                'anion_bvs_after': (res.get('anion_summary') or {}).get('anion_bvs_mean'),
            }
            row['gii_ratio'] = (round(g0 / g1, 2)
                                if g0 is not None and g1 not in (None, 0.0)
                                else None)
            row['n_screens_failed_after'] = sum(
                1 for k in _SCREENS_AFTER if row.get(k) is False)
            row['n_screens_failed_before'] = n_screens_before

            row['verdict'] = _verdict(n_screens_before,
                                      row['n_screens_failed_after'], g0, g1)

            # Reported alongside the verdict, not folded into it. Where the
            # geometry improves and the GII does not, that is a result about
            # bond valence rather than about the structure.
            if g0 is None or g1 is None:
                row['gii_direction'] = None
            elif g1 < g0:
                row['gii_direction'] = 'improves'
            elif g1 > g0:
                row['gii_direction'] = 'worsens'
            else:
                row['gii_direction'] = 'unchanged'
            row['screens_gii_disagree'] = bool(
                row['verdict'] in ('strongly supported', 'supported',
                                   'partially supported')
                and row['gii_direction'] == 'worsens')

            rows.append(row)

            if verbose:
                mark = '   [GII disagrees]' if row['screens_gii_disagree'] else ''
                print(f"  {fn}  [{variant}]")
                print(f"    {row['shift_applied']}")
                print(f"    screens {row['n_screens_failed_before']} -> "
                      f"{row['n_screens_failed_after']}   "
                      f"GII {row['gii_before']} -> {row['gii_after']}   "
                      f"[{row['verdict']}]{mark}")

    out = pd.DataFrame(rows)
    if len(out):
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        path = os.path.join(output_dir, f'eir_shift_test_{stamp}.csv')
        out.to_csv(path, index=False)
        print()
        print('-' * 78)
        if 'variant' in out.columns and out['variant'].nunique() > 1:
            print(pd.crosstab(out['variant'], out['verdict']).to_string())
            print()
            _needed = {'n_screens_failed_after', 'gii_after'}
            _scored = (out.dropna(subset=list(_needed))
                       if _needed <= set(out.columns) else out.iloc[0:0])
            if len(_scored):
                best = (_scored.sort_values(['n_screens_failed_after', 'gii_after'])
                               .drop_duplicates('filename'))
                print('  Better hypothesis per structure:')
                print('   ', best['variant'].value_counts().to_dict())
            else:
                print('  No structure was re-analysed successfully, so the two')
                print('  hypotheses cannot be compared. The verdicts above are')
                print('  reporting a failure to run, not a failure of the shift.')
        else:
            print(out['verdict'].value_counts().to_string())

        dis = out[out.get('screens_gii_disagree', False) == True]
        if len(dis):
            print()
            print(f'  SCREENS AND GII DISAGREE on {len(dis)} of {len(out)}:')
            print('  the shift clears or reduces screen failures while the GII')
            print('  worsens. Bond valence cannot distinguish a deficient')
            print('  coordination sphere from a sound one, so these are')
            print('  reported rather than resolved. Look at them by eye.')
            print()
            for _, r in dis.iterrows():
                print(f"    {r['icsd_code']}  {r['chemical_formula']:<18} "
                      f"[{r['variant']}]  screens "
                      f"{r['n_screens_failed_before']} -> "
                      f"{r['n_screens_failed_after']}   "
                      f"GII {r['gii_before']} -> {r['gii_after']}")

        print('-' * 78)
        print(f'  {len(written)} shifted CIFs written to {shifted_dir}')
        print(f'  comparison written to {path}')
        print()
        print('  Read this ALONGSIDE the quality CSV, not in place of it. A')
        print('  supported shift is evidence that the deposited cation and')
        print('  anion sublattices sit on different origins; it is not a')
        print('  correction, and the deposited entry remains the data of')
        print('  record until the source says otherwise.')
    if skipped:
        print()
        print(f'  {len(skipped)} not tested:')
        for fn, why in skipped[:10]:
            print(f'    {fn}: {why}')
    return out



def apply_shift_verdicts(dfq, shift_results, structures_csv=None,
                         sites_csv=None, verbose=True):
    """
    Write the tested verdicts back onto the site table and re-classify.

    The half-lattice screen proposes; this cell tests; PGRM must then say
    what the test found. Without this the G4 reason reads
    cation_on_wrong_origin for all 25 perovskite proposals, whether the
    shift cleared every screen it was failing (20 of them) or changed
    nothing the screens can see (1). Those are different claims and the
    reportable-error list should not flatten them.

    Only the single_site variant is used. all_cations is the CONTROL: it
    describes a whole cation sublattice on the wrong origin, and on the
    perovskites it is NOT supported 23 times of 25, which is what says
    these are single misplaced cations rather than a sublattice error.
    """
    if shift_results is None or not len(shift_results):
        return dfq
    ss = shift_results[shift_results.get("variant") == "single_site"]
    if not len(ss):
        return dfq

    _v, _e = {}, {}
    for _, r in ss.iterrows():
        fn = r.get("filename")
        if not fn:
            continue
        _v[fn] = r.get("verdict")
        _b, _a = r.get("n_screens_failed_before"), r.get("n_screens_failed_after")
        _gb, _ga = r.get("gii_before"), r.get("gii_after")
        _e[fn] = (f'shift {r.get("proposed_shift", "?")} on '
                  f'{r.get("shift_applied", r.get("sites_shifted", "?"))}: '
                  f'screens {_b} -> {_a}, GII {_gb} -> {_ga} '
                  f'[{r.get("verdict")}]')

    dfq = dfq.copy()
    _mask = dfq["proposed_shift"].notna() if "proposed_shift" in dfq else None
    dfq["shift_verdict"] = dfq["filename"].map(_v)
    dfq["shift_evidence"] = dfq["filename"].map(_e)
    if _mask is not None:
        # Only the site that carries the proposal gets the verdict; the
        # other sites of the same structure were not shifted.
        dfq.loc[~_mask, ["shift_verdict", "shift_evidence"]] = None

    if "classify_pgrm" in globals():
        dfq = classify_pgrm(dfq)
        if "apply_pgrm_suppression" in globals():
            dfq = apply_pgrm_suppression(dfq)
        if verbose:
            _st = dfq.drop_duplicates("filename")
            _g4 = _st[_st["structure_pgrm_code"].astype(str).str.startswith("G4")
                      | _st["structure_pgrm_reason"].astype(str).isin(
                          ["cation_on_wrong_origin", "cation_position_suspect",
                           "split_shell_cause_unknown",
                           "split_shell_not_diagnostic"])]
            print()
            print("  PGRM re-classified with the tested verdicts:")
            for _r, _n in _g4["structure_pgrm_reason"].value_counts().items():
                print(f"      {str(_r):32} {_n:4}")

    # Re-save so the reportable-error list is self-contained rather than
    # needing a join to eir_shift_test_*.csv.
    if sites_csv:
        dfq.to_csv(sites_csv, index=False)
    if structures_csv and "build_structure_table" in globals():
        build_structure_table(dfq).to_csv(structures_csv, index=False)
    if verbose and (sites_csv or structures_csv):
        print("  site and structure tables rewritten with the verdicts.")
    return dfq

def resolve_cif_directory(dfq, explicit=None, ask=True):
    """
    Find the folder holding the original CIFs, rather than asking for it.

    The notebook already knows: the batch cell picked it, the post-processing
    cell was handed it, and the outputs sit inside it. Asking again is friction
    for something already determined, so this looks in the obvious places and
    verifies each candidate the only way that settles it -- by checking that a
    CIF named in dfq is actually there.

    Order: an explicit argument, then any global holding a plausible path,
    then the parents of any 'outputs' directory among those globals, then the
    working directory and its subdirectories. Only if all of that fails, and
    only if ask is True, does it open a picker.
    """
    if dfq is None or 'filename' not in dfq.columns or not len(dfq):
        return explicit
    probe = str(dfq['filename'].iloc[0])

    def _ok(d):
        try:
            return bool(d) and os.path.exists(os.path.join(str(d), probe))
        except (TypeError, ValueError):
            return False

    if _ok(explicit):
        return explicit

    candidates = []
    g = globals()
    for name, val in list(g.items()):
        if not isinstance(val, str) or len(val) < 3 or name.startswith('__'):
            continue
        if not any(k in name.lower() for k in
                   ('dir', 'path', 'folder', 'cif', 'csv', 'directory')):
            continue
        candidates.append(val)
        # a results CSV or an outputs folder sits one level inside the CIFs
        if val.lower().endswith('.csv'):
            candidates.append(os.path.dirname(os.path.dirname(val)))
        base = os.path.basename(os.path.normpath(val)).lower()
        if base == 'outputs':
            candidates.append(os.path.dirname(os.path.normpath(val)))
    candidates += [os.getcwd(), os.path.dirname(os.getcwd())]
    try:
        for entry in os.listdir(os.getcwd()):
            full = os.path.join(os.getcwd(), entry)
            if os.path.isdir(full):
                candidates.append(full)
    except OSError:
        pass

    seen = set()
    for c in candidates:
        c = str(c)
        if c in seen:
            continue
        seen.add(c)
        if _ok(c):
            print(f'  CIF directory found: {c}')
            return c

    if not ask:
        return None
    try:
        import tkinter as tk
        from tkinter import filedialog
        root = tk.Tk()
        root.withdraw()
        root.attributes('-topmost', True)
        try:
            d = filedialog.askdirectory(
                title='Select the folder holding the original CIFs',
                mustexist=True)
        finally:
            root.quit()
            root.destroy()
        if _ok(d):
            return d
        if d:
            print(f'  {probe} is not in {d}; wrong folder?')
    except Exception as e:
        print(f'  could not open a folder picker ({e})')
    return None
